/* @autogenerated */
import {
  OBSERVED_SLO_EXCEL_COLUMNS,
  OBSERVED_SLO_EXCEL_SENSITIVE,
} from 'app/features/observe/observed-slo/model/observed-slo-excel-columns';
import { ObservedSourceRepository } from 'app/features/observe/observed-source/repository/observed-source-repository.service';
import { BaseExportAction } from 'app/shared/toolkit/action/base-export-action';
import { ObservedSlo } from 'app/features/observe/observed-slo/model/observed-slo.model';
import { ExportDefinition } from 'app/shared/toolkit/entity-export/entity-export.model';
import { take, map } from 'rxjs';
import { ObservedSloRepository } from 'app/features/observe/observed-slo/repository/observed-slo-repository.service';
import { Component, inject } from '@angular/core';

@Component({
  selector: 'observed-slo-view-export-action',
  standalone: false,
  templateUrl: './observed-slo-view-export-action.component.html',
})
export class ObservedSloViewExportActionComponent extends BaseExportAction<ObservedSlo> {
  protected readonly scope = 'observe/observed-slo';
  protected readonly repository = inject(ObservedSloRepository);
  private readonly originRepository = inject(ObservedSourceRepository);

  readonly definition: ExportDefinition<ObservedSlo> = {
    name: 'observe.observed-slo',
    scope: this.scope,
    // Las mismas columnas que la importación: el fichero se puede editar y volver a subir
    columns: OBSERVED_SLO_EXCEL_COLUMNS,
    sensitive: OBSERVED_SLO_EXCEL_SENSITIVE,
    references: {
      origin: {
        names: (refs) =>
          this.originRepository.values({ uids: refs, limit: refs.length }).pipe(
            take(1),
            map((found) => Object.fromEntries(found.map((one) => [one.uid, String(one.code ?? '')]))),
          ),
      },
    },
    source: {
      acl: () => this.repository.checkAcl(),
      list: (filter) => this.repository.list(filter).pipe(take(1)),
    },
  };
}
